<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\SnippetAsset\Application\Usecase\Retrieve;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Connector\FileStorage\BinaryContent;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\SnippetAssetRef;
use Civi\Lughauth\Features\Document\SnippetAsset\Application\Service\Visibility\SnippetAssetVisibilityService;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\Gateway\SnippetAssetReadGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class SnippetAssetRetrieveUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly SnippetAssetVisibilityService $visibility,
        private readonly SnippetAssetReadGateway $reader
    ) {
    }

    public function allowRetrieve(?SnippetAssetRef $ref = null): Allow
    {
        $this->logDebug("Check allow of retrieve usecase for Snippet asset");
        $span = $this->startSpan("Check allow of retrieve usecase for Snippet asset");
        try {
            $result = $this->dispatcher->dispatch(new SnippetAssetRetrieveAllowDecision(Allow::allowed('retrieve', 'Allowed to retrieve by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function hiddenFields(?SnippetAssetRef $ref = null): array
    {
        $this->logDebug("Check hidden fields usecase for Snippet asset");
        $span = $this->startSpan("Check hidden fields usecase for Snippet asset");
        try {
            return $this->visibility->fieldsToHide($ref);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieve(string $uid): SnippetAssetRetrieveResult
    {
        $this->logDebug("Run retrieve usecase for Snippet asset");
        $span = $this->startSpan("Run retrieve usecase for Snippet asset");
        try {
            $ref = new SnippetAssetRef($uid);
            $allow = $this->allowRetrieve($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to retrieve Snippet asset');
            }
            if (!$result = $this->visibility->retrieveVisible($ref)) {
                throw new NotFoundException($uid);
            }
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new SnippetAssetRetrieveResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveContent(string $uid): BinaryContent
    {
        $this->logDebug("Run retrieve Content file usecase for Snippet asset");
        $span = $this->startSpan("Run retrieve Content file usecase for Snippet asset");
        try {
            $ref = new SnippetAssetRef($uid);
            $allow = $this->allowRetrieve($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to retrieve content of Snippet asset');
            }
            if (!$visible = $this->visibility->retrieveVisible($ref)) {
                throw new NotFoundException($uid);
            }
            $url = $visible->getContent();
            if (null === $url) {
                throw new NotFoundException($uid);
            }
            return $this->reader->readContent($url);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
